CREATE FUNCTION fyth_usage_private.increment_event(p_event text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE today date := pg_catalog.timezone('UTC',pg_catalog.now())::date;
BEGIN
 IF p_event IS NULL OR p_event NOT IN ('diagnosis_requested','diagnosis_ready','diagnosis_withheld','diagnosis_error','diagnosis_disconnected') THEN RAISE EXCEPTION 'invalid event'; END IF;
 DELETE FROM fyth_usage_private.daily_counts WHERE day < today - 29;
 INSERT INTO fyth_usage_private.daily_counts AS totals(day,event,count) VALUES(today,p_event,1)
 ON CONFLICT(day,event) DO UPDATE SET count = totals.count + 1;
